/**
 * 两份文案表（供测试直接读取）。
 * `en: typeof zh` 只保证**键**相同，不保证数组长度一致——漏翻一条步骤 typecheck 不报，
 * 所以 help-content.test.ts 用这里逐页比对中英步骤条数。
 */
export const TRANSLATIONS = { zh, en };

void i18n.use(initReactI18next).init({
  resources: {
    zh: { translation: zh },
    en: { translation: en },
  },
  lng: 'zh',
  fallbackLng: 'zh',
  interpolation: { escapeValue: false },
});

export default i18n;
